const x=$input.first().json;
const failures=[];
if(x.ok!==true) failures.push('health_not_ok');
if(String(x.version)!=='2.1.0') failures.push(`version=${x.version}`);
if(x.manual_editor_foundation!==true) failures.push('manual_editor_foundation');
if(x.variant_planner!==true) failures.push('variant_planner');
if(String(x.production_edit_contract)!=='SM3_PRODUCTION_EDIT_V1') failures.push(`contract=${x.production_edit_contract}`);
if(failures.length) throw new Error('SM3_EDIT_FOUNDATION_ASSERT_FAILED: '+failures.join(','));
return [{json:{status:'SM3_EDIT_FOUNDATION_HEALTH_PASS',version:x.version,production_edit_contract:x.production_edit_contract,manual_editor_foundation:x.manual_editor_foundation,variant_planner:x.variant_planner,completed_at:new Date().toISOString()}}];
